package com.lamggm.rospocket;
import android.view.*;import android.widget.*;import android.app.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import org.json.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31) @LooperMode(LooperMode.Mode.PAUSED)
public class DashboardActivityTest {
 final ConnectionActivityTest f=new ConnectionActivityTest();RobotDashboardTest.Fake nativeApi;
 @Before public void setup()throws Exception{f.setup();nativeApi=new RobotDashboardTest.Fake();f.set("bridge",nativeApi);nativeApi.snapshot=new JSONObject(nativeApi.snapshot).put("topics",RobotDashboardTest.topics("/robot/robot_description")).toString();f.set("lastUi",0L);f.tick();f.paint();}
 @After public void cleanup()throws Exception{f.cleanup();}
 View root(){return f.a.getWindow().getDecorView().findViewWithTag("app-root");}
 DashboardBoard board(){DashboardBoard b=root().findViewWithTag("dashboard-board");assertNotNull("Native dashboard must expose its editor",b);return b;}

 @Test public void leavingForegroundDiscardsDraftButPreservesSavedLayout()throws Exception{DashboardBoard b=board();b.edit();b.resize("plot",4,3);assertTrue(b.save());String saved=b.layout().encode();b.edit();b.resize("plot",2,2);f.call("onStop",new Class<?>[]{});assertFalse(b.editing());assertEquals(saved,new DashboardStore(f.a.getFilesDir()).load().encode());}
 @Test public void sensorAndChartActualViewportGrowAndTheirTechnicalControlsRemainReachable(){
  f.controller.visible();f.a.findViewById(R.id.nav_monitor).performClick();DashboardBoard b=board();b.edit();b.resize("sensors",2,2);b.resize("plot",2,2);measure(1280);
  View sensor=root().findViewWithTag("sensor-surface"),chart=root().findViewById(R.id.plot_chart);int oldSensor=sensor.getHeight(),oldChart=chart.getHeight();b.resize("sensors",4,4);b.resize("plot",4,4);measure(1280);
  assertTrue("Sensor viewport "+oldSensor+" -> "+sensor.getHeight(),sensor.getHeight()>oldSensor+100);assertTrue("Chart viewport "+oldChart+" -> "+chart.getHeight(),chart.getHeight()>oldChart+100);b.cancel();measure(1280);
  root().findViewWithTag("preview-open:plot").performClick();f.paint();Dialog detail=ShadowDialog.getLatestDialog();assertTrue(detail.isShowing());View plot=detail.getWindow().getDecorView();plot.findViewWithTag("plot-settings").performClick();assertEquals(View.VISIBLE,plot.findViewWithTag("plot-configuration").getVisibility());detail.dismiss();f.paint();
  assertNotNull(root().findViewWithTag("sensor-details"));root().findViewWithTag("preview-open:robot").performClick();f.paint();detail=ShadowDialog.getLatestDialog();assertTrue(detail.isShowing());detail.getWindow().getDecorView().findViewWithTag("robot-options").performClick();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();assertTrue("Model options dialog visible",d.isShowing());assertNotNull("TF control remains accessible in options",d.findViewById(android.R.id.content).findViewWithTag("robot-tf-mode"));d.dismiss();f.paint();assertNotNull("Dialog dismissal restores the same technical controls after main-loop delivery",detail.getWindow().getDecorView().findViewWithTag("robot-tf-mode"));detail.dismiss();f.paint();assertNotNull(root().findViewWithTag("robot-tf-mode"));
 }
 void measure(int width){View r=root();r.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(850,View.MeasureSpec.EXACTLY));r.layout(0,0,width,850);}
 @Test public void actualMenuResizesSavedLayoutWithoutReplacingModelOrChangingReaders()throws Exception{DashboardBoard b=board();RobotModelView model=root().findViewWithTag("robot-model");java.lang.reflect.Field z=RobotModelView.class.getDeclaredField("zoom");z.setAccessible(true);z.setFloat(model,1.75f);Object parent=model.getParent();int starts=nativeApi.starts,subs=nativeApi.subscriptions,descriptions=nativeApi.descriptionStarts;
  root().findViewWithTag("dashboard-edit").performClick();assertTrue(b.editing());root().findViewWithTag("layout-options:sensors").performClick();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();ListView list=d.getListView();int at=-1;for(int i=0;i<list.getCount();i++)if(list.getItemAtPosition(i).toString().startsWith("4 × 3"))at=i;assertTrue(at>=0);list.performItemClick(list.getAdapter().getView(at,null,list),at,at);f.paint();assertEquals(4,b.layout().get("sensors").width);b.resize("robot",2,2);b.moveBefore("sensors","robot");measure(1280);root().findViewWithTag("dashboard-save").performClick();assertFalse(b.editing());assertEquals(4,new DashboardStore(f.a.getFilesDir()).load().get("sensors").width);assertSame(model,root().findViewWithTag("robot-model"));assertSame(parent,model.getParent());assertEquals(1.75f,z.getFloat(model),0);assertEquals(starts,nativeApi.starts);assertEquals(subs,nativeApi.subscriptions);assertEquals(descriptions,nativeApi.descriptionStarts);
 }
 @Test public void backAndSectionChangeDiscardOnlyUnsavedLayout()throws Exception{DashboardBoard b=board();String baseline=b.layout().encode();b.edit();b.resize("plot",4,4);f.a.onBackPressed();assertFalse(b.editing());assertEquals(baseline,b.layout().encode());b.edit();b.resize("plot",4,3);f.a.findViewById(R.id.nav_connection).performClick();assertFalse(b.editing());assertEquals(baseline,b.layout().encode());assertEquals(baseline,new DashboardStore(f.a.getFilesDir()).load().encode());}
 @Test public void phoneClampDoesNotOverwriteTabletSpansAndViewportReallyGrows(){DashboardBoard b=board();b.edit();b.resize("robot",2,2);measure(1280);View preview=root().findViewWithTag("robot-model");int initial=preview.getHeight();b.resize("robot",4,4);measure(1280);assertTrue("Resizing must enlarge the actual model, not an empty card border",preview.getHeight()>initial+100);measure(400);assertEquals(4,b.layout().get("robot").width);assertTrue(preview.getWidth()>0);assertTrue(preview.getWidth()<=root().getWidth());}
}
